mapper.select:
SELECT 
FROM diary_cover_design_elements
WHERE id = #{elementId}
  AND design_id = #{designId}

SELECT e.id, e.design_id, e.element_type, e.text_content, e.image_url, e.style_type, e.color_type, e.photo_style, e.text_font, e.text_color, e.position_x, e.position_y, e.width, e.height, e.rotation, e.z_index, e.created_at, e.updated_at FROM diary_cover_design_elements e JOIN diary_cover_designs d ON d.id = e.design_id WHERE d.user_id = #{userId} AND e.design_id IN
#{designId}
ORDER BY e.design_id, e.z_index ASC, e.id ASC

mapper.update:
UPDATE diary_cover_design_elements
SET position_x = #{positionX},
    position_y = #{positionY},
    updated_at = NOW()
WHERE id = #{elementId}
  AND design_id = #{designId}

UPDATE diary_cover_design_elements
SET width = #{width},
    height = #{height},
    updated_at = NOW()
WHERE id = #{elementId}
  AND design_id = #{designId}

UPDATE diary_cover_design_elements
SET rotation = #{rotation},
    updated_at = NOW()
WHERE id = #{elementId}
  AND design_id = #{designId}

UPDATE diary_cover_design_elements
SET z_index = #{zIndex},
    updated_at = NOW()
WHERE id = #{elementId}
  AND design_id = #{designId}

UPDATE diary_cover_design_elements
SET photo_style = #{photoStyle},
    updated_at = NOW()
WHERE id = #{elementId}
  AND design_id = #{designId}

UPDATE diary_cover_design_elements
SET text_content = #{textContent},
    updated_at = NOW()
WHERE id = #{elementId}
  AND design_id = #{designId}

